    ownerDisplay.style.cssText = 'padding:8px 12px; margin-bottom:4px; background:#f0f0f0; font-size:0.85em; border-bottom:1px solid #ddd;';
    ownerDisplay.innerHTML = `<strong>所有者:</strong> ${ownerName}`;
